choose.when:
SELECT cdtype, codecd, codenm, remark, dspord, useyn FROM haba900t_tbl WHERE cdtype = #{cdtype}
AND useyn = 'Y'
ORDER BY dspord, codecd

mapper.select:
SELECT A.pgmid, A.pgmnm, A.upmucd, C.codenm AS upmunm, A.grpcd, B.grpnm, A.dspord, A.useyn FROM haaa800t_tbl A LEFT OUTER JOIN haaa810t_tbl B ON A.upmucd = B.upmucd AND A.grpcd = B.grpcd LEFT OUTER JOIN haba900t_tbl C ON C.cdtype = '320' AND A.upmucd = C.codecd WHERE 1=1
AND A.upmucd = #{upmucd}
AND A.grpcd = #{grpcd}
AND A.pgmnm LIKE CONCAT('%', #{pgmnm}, '%')
ORDER BY A.dspord

SELECT upmucd, grpcd, grpnm, dspord, useyn FROM haaa810t_tbl WHERE 1=1
AND upmucd = #{upmucd}
ORDER BY upmucd, dspord

mapper.delete:
DELETE FROM haaa810t_tbl WHERE upmucd = #{upmucd} AND grpcd = #{grpcd};
DELETE FROM haba930t_tbl WHERE upmucd = #{upmucd} AND grpcd = #{grpcd};
DELETE FROM haba940t_tbl WHERE upmucd = #{upmucd} AND grpcd = #{grpcd};
